<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {zonedCandidates} from '../../shared/dates.mjs';import {currentZone,localInput} from '../domain/todos';import {useApplicationSettings} from '../stores/settings';import {useAgents} from '../stores/agents';import {useOrganizer} from '../stores/organizer';import {useModelSettings} from '../stores/models';
import SkField from './ui/SkField.vue';import SkTextarea from './ui/SkTextarea.vue';import SkDateTimeField from './ui/SkDateTimeField.vue';import SkSelect from './ui/SkSelect.vue';import SkFieldset from './ui/SkFieldset.vue';import SkButton from './ui/SkButton.vue';import Icon from './Icon.vue';
const settings=useApplicationSettings(),agents=useAgents(),organizer=useOrganizer(),model=useModelSettings(),localError=ref(''),needsReview=ref(false),emit=defineEmits<{submitted:[sourceId:string];models:[]}>();
const candidates=computed(()=>{try{return organizer.text.sourceTime?zonedCandidates(organizer.text.sourceTime,currentZone()):[];}catch{return [];}});
watch(()=>currentZone(),zone=>{if(organizer.text.timeZone!==zone&&organizer.text.sourceTime){const choices=zonedCandidates(organizer.text.sourceTime,organizer.text.timeZone);const at=choices.length===1?choices[0]:organizer.text.sourceChoice;if(at!==null&&choices.includes(at)){organizer.text.sourceTime=localInput({atMs:at,timeZone:organizer.text.timeZone,localText:organizer.text.sourceTime},zone);organizer.text.sourceChoice=at;}else needsReview.value=true;}organizer.text.timeZone=zone;},{immediate:true});
function updateTime(value:string){organizer.text.sourceTime=value;organizer.text.sourceChoice=null;needsReview.value=false;localError.value='';}
async function submit(){if(!model.ready||model.saving||!settings.ready||settings.loading||settings.saving||!agents.states.organizer.ready)return;localError.value='';try{if(needsReview.value)throw Error('请重新核对来源时间后再整理。');let at:number|null=null;if(organizer.text.sourceTime){if(!candidates.value.length)throw Error('这个来源时刻不存在，请重新选择。');at=candidates.value.length===1?candidates.value[0]:organizer.text.sourceChoice;if(at===null||!candidates.value.includes(at))throw Error('来源时刻出现两次，请选择具体一次。');}const run=await organizer.organize(at);if(run.sourceId)emit('submitted',run.sourceId);}catch(e){localError.value=e instanceof Error?e.message:'';}}
onMounted(()=>{if(!model.ready&&!model.loading)void model.load().catch(()=>{});if(!agents.states.organizer.ready&&!agents.states.organizer.loading)void agents.load('organizer').catch(()=>{});});
</script>
<template><form class="text-intake" @submit.prevent="submit"><div class="dialog-body"><SkFieldset :disabled="organizer.starting||!settings.ready||settings.loading||settings.saving"><SkField label="要整理的原文" required><SkTextarea v-model="organizer.text.body" rows="7" maxlength="64000" placeholder="贴入纪要、邮件或一段工作记录。班班先整理成候选，你签收后才成为正式事项。" required/></SkField><SkField class="source-anchor" label="来源时间（可选）" :error="needsReview?'请重新核对来源时间。':''"><SkDateTimeField :model-value="organizer.text.sourceTime" @update:model-value="updateTime"/></SkField><SkField v-if="candidates.length>1" label="来源时刻出现两次"><SkSelect v-model="organizer.text.sourceChoice" :options="candidates.map((at,index)=>({value:at,label:index===0?'较早一次':'较晚一次'}))" placeholder="请选择具体一次"/></SkField><p class="muted">不填时按首次录入时间理解“今天／下周”；相同文本重试沿用原锚点。原文直接交给你配置的模型。</p><p v-if="localError||organizer.error||!model.ready&&model.error||agents.states.organizer.error||settings.error" class="form-error" role="alert">{{localError||organizer.error||model.error||agents.states.organizer.error||settings.error}}</p><button class="text-button" type="button" @click="emit('models')">配置或检查模型服务<Icon name="arrow"/></button></SkFieldset></div><footer class="dialog-footer"><span class="muted">先整理成候选，签收前不入库。</span><SkButton kind="commit" type="submit" :loading="organizer.starting" :disabled="organizer.running||organizer.starting||!model.ready||model.saving||!settings.ready||settings.loading||settings.saving||!agents.states.organizer.ready"><Icon name="check"/>开始整理</SkButton></footer></form></template>
